import{_ as e,c as i,o as l,ae as t}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"安装 Persim","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/installation.md","filePath":"zh-CN/guide/installation.md","lastUpdated":1795170900000}'),r={name:"zh-CN/guide/installation.md"};function o(s,a,n,d,p,h){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="安装-persim" tabindex="-1">安装 Persim <a class="header-anchor" href="#安装-persim" aria-label="Permalink to &quot;安装 Persim&quot;">​</a></h1><p>下载、设为默认浏览器，再把书签带过来。</p><h2 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to &quot;下载与安装&quot;">​</a></h2><ol><li>打开 <a href="https://apps.apple.com/app/id6835099132" target="_blank" rel="noreferrer">Mac App Store</a>，搜索 Persim。</li><li>下载完成后，把应用拖进「应用程序」文件夹；系统询问时确认即可。</li><li>想设为默认浏览器，打开「系统设置 → 默认网页浏览器」，选择 Persim。</li></ol><p>需要 macOS 12 及以上，Apple Silicon 和 Intel 芯片都支持。</p><h2 id="第一次打开" tabindex="-1">第一次打开 <a class="header-anchor" href="#第一次打开" aria-label="Permalink to &quot;第一次打开&quot;">​</a></h2><ul><li>在 <code>persim://settings</code> 的「常规」里选择外观、主色和书签栏显示方式。</li><li>界面语言有 25 种；切换后重新打开窗口生效。</li><li>新标签页已经放好常用网站和 AI 直达入口，直接用即可。</li></ul><h2 id="把书签带过来" tabindex="-1">把书签带过来 <a class="header-anchor" href="#把书签带过来" aria-label="Permalink to &quot;把书签带过来&quot;">​</a></h2><ol><li>在 Chrome 或 Edge 里把书签导出成 HTML 文件。</li><li>打开 Persim 的书签管理器，选择「导入 HTML」并选中文件。</li><li>多层文件夹会还原，重复网址会自动跳过；书签栏还可以随时拖动排序。</li></ol><h2 id="后续更新" tabindex="-1">后续更新 <a class="header-anchor" href="#后续更新" aria-label="Permalink to &quot;后续更新&quot;">​</a></h2><p>在 Mac App Store 的「更新」里获取新版本，已有数据会保留。</p>',11)])])}const _=e(r,[["render",o]]);export{m as __pageData,_ as default};
